using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;
using System.Windows.Media;

namespace ToadDesign;

/// <summary>
/// Geometry of Tabler icons in the 24×24 box, read from the embedded tabler-outline.bin (generated by tools/IconGen).
/// Each icon is parsed on first use and frozen, so it can be shared by every thread.
/// </summary>
internal static class IconGeometry
{
    private const string ResourceSuffix = "tabler-outline.bin";
    private static readonly object Gate = new();
    private static string[][]? _lines;
    private static (Geometry? Stroke, Geometry? Fill)?[]? _cache;

    /// <summary>The stroked and the filled part of <paramref name="symbol"/>; both null for <see cref="Symbol.None"/>.</summary>
    public static (Geometry? Stroke, Geometry? Fill) Get(Symbol symbol)
    {
        var index = (int)symbol - 1;
        if (index < 0) return (null, null);
        lock (Gate)
        {
            _lines ??= Load();
            _cache ??= new (Geometry?, Geometry?)?[_lines.Length];
            if (index >= _lines.Length) return (null, null);
            return _cache[index] ??= (Parse(_lines[index][1]), Parse(_lines[index][2]));
        }
    }

    /// <summary>The member name the generator gave to the data row of <paramref name="symbol"/> (consistency check).</summary>
    public static string MemberNameOf(Symbol symbol)
    {
        lock (Gate)
        {
            _lines ??= Load();
            var name = _lines[(int)symbol - 1][0];
            var member = string.Concat(name.Split('-').Where(p => p.Length > 0).Select(p => char.ToUpperInvariant(p[0]) + p.Substring(1)));
            return char.IsDigit(member[0]) ? "Number" + member : member;
        }
    }

    private static Geometry? Parse(string data)
    {
        if (data.Length == 0) return null;
        var geometry = Geometry.Parse(data);
        geometry.Freeze();
        return geometry;
    }

    private static string[][] Load()
    {
        var assembly = typeof(IconGeometry).Assembly;
        // Found by suffix: ILRepack keeps embedded resource names, but a renamed build may not.
        var name = assembly.GetManifestResourceNames().FirstOrDefault(n => n.EndsWith(ResourceSuffix, StringComparison.Ordinal))
                   ?? throw new InvalidOperationException($"Icon data {ResourceSuffix} is missing from {assembly.GetName().Name}.");
        using var stream = assembly.GetManifestResourceStream(name)!;
        using var gzip = new GZipStream(stream, CompressionMode.Decompress);
        using var reader = new StreamReader(gzip, Encoding.UTF8);
        return reader.ReadToEnd().Split(new[] { '\n' }, StringSplitOptions.RemoveEmptyEntries).Select(l => l.Split('\t')).ToArray();
    }
}
